"use client";
import React from "react";
import Link from "next/link";

export const BrandCard = ({ brand }: { brand: any }) => {
  return (
    <Link href={`/brands/${brand.slug}`} className="group">
      <div
        style={{ backgroundColor: brand.color }}
        className="relative aspect-3/3 overflow-hidden rounded-[3rem] flex justify-center items-center"
      >
        {" "}
        <img src={brand.logo} alt={brand.name} className="w-32 object-contain invert" />
      </div>
      <div className="mt-3 px-1">
        <h3 className="text-foreground font-bold text-sm truncate uppercase tracking-tight">
          {brand.name}
        </h3>
      </div>
    </Link>
  );
};
